/** Controls are mutable values shared by accessible DOM inputs and the scene.
 * The built-in `piece` key is the focused or pointed-at piece, or null.
 */
export type ControlKey = string;

export type Controls = {
  /** What a control is set to, or null if the reader has not touched it. */
  get(key: ControlKey): number | null;
  set(key: ControlKey, value: number | null): void;
  /** Calls `listener` whenever any value changes. Returns how to stop. */
  subscribe(listener: () => void): () => void;
};

export function createControls(): Controls {
  const values = new Map<ControlKey, number>();
  const listeners = new Set<() => void>();
  return {
    get: (key) => values.get(key) ?? null,
    set(key, value) {
      if ((values.get(key) ?? null) === value) return;
      if (value === null) values.delete(key);
      else values.set(key, value);
      for (const listener of listeners) listener();
    },
    subscribe(listener) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}

import type { BeatFormation, Formation } from "./formation.ts";

export type ChapterRole = "opening" | "who" | "where" | "how" | "what" | "outcomes" | "others" | "close";
export type BeatDef = { id: string; height: number };
export type ChapterDef = {
  id: string;
  number: number;
  name: string;
  role: ChapterRole;
  beats: readonly BeatDef[];
};
export type StoryDef = { pieces: number; chapters: readonly ChapterDef[] };
export type BeatIdOf<S extends StoryDef> = S["chapters"][number]["beats"][number]["id"];

/** Beats are flattened in reading order; the story remains the source of truth. */
export function beatsOf<S extends StoryDef>(story: S): S["chapters"][number]["beats"][number][] {
  return story.chapters.flatMap((chapter) => chapter.beats);
}

export function beatIndex(story: StoryDef, id: string): number {
  return beatsOf(story).findIndex((beat) => beat.id === id);
}

export function beatHeight(story: StoryDef, id: string): number {
  const beat = beatsOf(story).find((entry) => entry.id === id);
  if (!beat) throw new Error(`Unknown beat: ${id}`);
  return beat.height;
}

/** The chapter being read, including while travelling between two beats. */
export function chapterAt(story: StoryDef, beat: number): string | undefined {
  const chapters = story.chapters.flatMap((chapter) => chapter.beats.map(() => chapter.id));
  const nearest = Number.isFinite(beat) ? Math.round(beat) : 0;
  return chapters[Math.min(Math.max(nearest, 0), chapters.length - 1)];
}

/**
 * How much of a chapter's own scene is showing at `beat`: 1 on its beats,
 * easing to 0 over the travel from the beat before and to the beat after,
 * so a scene grows out of the last one instead of appearing.
 */
export function chapterPresence(story: StoryDef, id: string, beat: number): number {
  let first = 0;
  for (const chapter of story.chapters) {
    if (chapter.id === id) {
    if (chapter.id === id) {
      if (!chapter.beats.length || !Number.isFinite(beat)) return 0;
      const last = first + chapter.beats.length - 1;
      return Math.max(0, 1 - Math.max(first - beat, beat - last, 0));
    }
    first += chapter.beats.length;
  }
  return 0;
}

export function chapterNear(story: StoryDef, id: string, beat: number, reach = 1.5): boolean {
  let first = 0;
  for (const chapter of story.chapters) {
    if (chapter.id === id) {
      return chapter.beats.length > 0 && beat >= first - reach && beat <= first + chapter.beats.length - 1 + reach;
    }
    first += chapter.beats.length;
  }
  return false;
}

export function chapterNumber(story: StoryDef, id: string): number {
  return story.chapters.find((chapter) => chapter.id === id)?.number ?? 0;
}

/** Reports content mistakes before the scene tries to render the bundle. */
export function checkStory(
  story: StoryDef,
  formations: Readonly<Partial<Record<string, BeatFormation>>>,
  faces: readonly { beat: string; piece: number }[] = [],
): string[] {
  const problems: string[] = [];
  if (!Number.isInteger(story.pieces) || story.pieces < 1) problems.push("pieces must be a positive integer");
  if (story.chapters.length === 0) problems.push("story must have a chapter");
  const ids = new Set<string>();
  const beats = new Set<string>();
  const register = (id: string) => {
    if (!id.trim()) problems.push("id must not be empty");
    if (ids.has(id)) problems.push(`id used twice: ${id}`);
    ids.add(id);
  };
/** Surface, light and text colours can change without changing the story. */
export type Look = {
  id: string;
  name?: string;
  ground: string;
  ink: string;
  faint: string;
  accent: string;
  surface: { color: string; roughness: number; glows: boolean };
  lights: { ambient: number; key: number; fill: number; rim: number };
  floor: "matte" | "none";
  shadows: boolean;
};

export function parseLook(value: string | null | undefined, looks: readonly Look[], defaultId?: string): string {
  const fallback = looks.find((look) => look.id === defaultId) ?? looks[0];
  if (!fallback) throw new Error("A story needs at least one look");
  return looks.find((look) => look.id === value)?.id ?? fallback.id;
}

export function lookFromSearch(search: string, looks: readonly Look[], defaultId?: string): string {
  return parseLook(new URLSearchParams(search).get("look"), looks, defaultId);
}

/** Preserves unrelated parameters and leaves the default look out of the URL. */
export function searchWithLook(search: string, id: string, defaultId: string): string {
  const params = new URLSearchParams(search);
  if (id === defaultId) params.delete("look");
  else params.set("look", id);
  const text = params.toString();
  return text ? `?${text}` : "";
}
